/**
 * Registration export generators — CSV, XLSX, PDF, DOCX, JSON, TXT, HTML.
 *
 * Server-only module. Every format is built from the persisted form +
 * submissions (nothing photographic/placeholder): each export is a genuine
 * file of its advertised type, generated by the library for that format.
 *
 * Shared row/column building comes from src/lib/forms.ts so formats stay in
 * agreement about labels, removed fields and answer formatting.
 */
import ExcelJS from "exceljs";
import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
import {
    AlignmentType,
    Document,
    HeadingLevel,
    Packer,
    PageOrientation,
    Paragraph,
    Table,
    TableCell,
    TableRow,
    TextRun,
    WidthType,
} from "docx";
import type { Form, FormField } from "../../types/forms.ts";
import {
    buildExportColumns,
    buildExportRows,
    slugifyFormTitle,
    type ExportColumn,
    type ExportSubmission,
} from "../forms.ts";

export type ExportFormatId = "csv" | "xlsx" | "pdf" | "docx" | "json" | "txt" | "html";

export const EXPORT_FORMATS: { id: ExportFormatId; label: string; contentType: string }[] = [
    { id: "csv", label: "CSV — spreadsheets (Excel, Google Sheets)", contentType: "text/csv;charset=utf-8" },
    { id: "xlsx", label: "Excel workbook (.xlsx)", contentType: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" },
    { id: "pdf", label: "PDF report (.pdf)", contentType: "application/pdf" },
    { id: "docx", label: "Word document (.docx)", contentType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document" },
    { id: "json", label: "JSON data (.json)", contentType: "application/json;charset=utf-8" },
    { id: "txt", label: "Plain text (.txt)", contentType: "text/plain;charset=utf-8" },
    { id: "html", label: "HTML report (.html)", contentType: "text/html;charset=utf-8" },
];

export interface ExportPayload {
    form: {
        id: string;
        title: string;
        description: string;
        status: string;
        fields: FormField[];
        createdAt: string | null;
        updatedAt: string | null;
        opensAt: string | null;
        closesAt: string | null;
    };
    submissions: ExportSubmission[];
}

/** UTC-stable timestamp used consistently in every export. */
function formatStamp(iso: string | null): string {
    if (!iso) return "";
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return "";
    const p = (n: number) => String(n).padStart(2, "0");
    return `${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}/${d.getUTCFullYear()}, ${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`;
}

function escapeHtml(s: string): string {
    return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

/** Rows shared by the tabular formats (csv/xlsx/pdf/docx/html/txt). */
function tableModel(payload: ExportPayload): { columns: ExportColumn[]; rows: string[][]; columnWidths: number[] } {
    const columns = buildExportColumns(payload.form);
    const exportRows = buildExportRows(payload.form, payload.submissions, formatStamp);

    // Removed-field columns appear dynamically when any historical answer
    // references a field deleted from the form, so data is never discarded.
    const removedIds: string[] = [];
    for (const s of payload.submissions) {
        for (const id of s.removedFieldIds ?? []) {
            if (!removedIds.includes(id)) removedIds.push(id);
        }
    }
    const removedCols: ExportColumn[] = removedIds.map(id => ({
        key: `removed_${id}`,
        header: "Removed field",
    }));
    const cols = [...columns, ...removedCols];

    const rows: string[][] = exportRows.map(r => cols.map(c => {
        if (c.key === "__submittedAt") return r.submittedAt ?? "";
        if (c.key === "__name") return r.userName;
        if (c.key === "__email") return r.userEmail;
        if (c.key.startsWith("removed_")) {
            const fieldId = c.key.slice("removed_".length);
            const raw = payload.submissions.find(s => s.removedFieldIds?.includes(fieldId))?.answers[fieldId];
            return Array.isArray(raw) ? raw.join(", ") : typeof raw === "boolean" ? (raw ? "Yes" : "No") : String(raw ?? "");
        }
        return r.cells[c.key] ?? "";
    }));

    const wide = cols.map((col, idx) => {
        let w = col.header.length;
        for (const r of rows) w = Math.max(w, (r[idx] ?? "").length);
        return Math.min(Math.max(w + 2, 8), 60);
    });
    return { columns: cols, rows, columnWidths: wide };
}

function formattedRemoved(s: ExportSubmission, id: string): string {
    const v = s.answers[id];
    if (Array.isArray(v)) return v.join(", ");
    if (typeof v === "boolean") return v ? "Yes" : "No";
    return String(v ?? "");
}

// ── CSV ─────────────────────────────────────────────────────────────────────

export function toCsv(payload: ExportPayload): string {
    const { columns, rows } = tableModel(payload);
    const cell = (v: string) => {
        // CSV injection guard (same convention as lib/csvUtils.ts).
        let out = v ?? "";
        if (/^[=+\-@\t\r]/.test(out)) out = `'${out}`;
        return `"${out.replace(/"/g, '""')}"`;
    };
    const lines = [columns.map(c => cell(c.header)).join(",")];
    for (const r of rows) lines.push(r.map(cell).join(","));
    // BOM keeps Excel/Sheets decoding UTF-8 for Unicode names and multiline answers.
    return "\uFEFF" + lines.join("\r\n") + "\r\n";
}

// ── XLSX ────────────────────────────────────────────────────────────────────

export async function toXlsx(payload: ExportPayload): Promise<Buffer> {
    const { columns, rows, columnWidths } = tableModel(payload);
    const wb = new ExcelJS.Workbook();
    wb.creator = "ReLU Club admin";
    wb.created = new Date();

    const ws = wb.addWorksheet("Submissions");
    ws.addRow(columns.map(c => c.header)).font = { bold: true };
    ws.views = [{ state: "frozen", ySplit: 1 }];
    for (const r of rows) ws.addRow(r);
    // Cells are written as strings on purpose: phone numbers, roll numbers and
    // leading-zero IDs must not be reinterpreted by Excel. Column widths sized
    // from content so long answers stay visible.
    for (let i = 0; i < columns.length; i++) {
        ws.getColumn(i + 1).width = columnWidths[i] ?? 12;
    }

    const meta = wb.addWorksheet("Form details");
    meta.addRow(["Field", "Value"]).font = { bold: true };
    const details: [string, string][] = [
        ["Form title", payload.form.title],
        ["Description", payload.form.description],
        ["Status", payload.form.status],
        ["Opened at", payload.form.opensAt ? formatStamp(payload.form.opensAt) : ""],
        ["Closes at", payload.form.closesAt ? formatStamp(payload.form.closesAt) : ""],
        ["Created at", payload.form.createdAt ? formatStamp(payload.form.createdAt) : ""],
        ["Last updated", payload.form.updatedAt ? formatStamp(payload.form.updatedAt) : ""],
        ["Submissions exported", String(payload.submissions.length)],
        ["Exported at", formatStamp(new Date().toISOString())],
    ];
    for (const [k, v] of details) meta.addRow([k, v]);
    meta.getColumn(1).width = 22;
    meta.getColumn(2).width = 60;

    const buf = await wb.xlsx.writeBuffer();
    return Buffer.from(buf);
}

// ── PDF ─────────────────────────────────────────────────────────────────────
// jsPDF's standard fonts cover Latin-1 (WinAnsi). Latin characters with
// accents render correctly; scripts outside that range are transliterated —
// see sanitizeForPdf — so the file stays readable everywhere.

function sanitizeForPdf(s: string): string {
    return s
        .normalize("NFKD")
        .replace(/[\u0300-\u036f]/g, "") // strip combining accents
        .replace(/[\u2018\u2019]/g, "'")
        .replace(/[\u201C\u201D]/g, '"')
        .replace(/[\u2013\u2014]/g, "-")
        .replace(/\u2026/g, "...")
        .replace(/[^\x20-\x7E\xA0-\xFF\n]/g, "") // drop anything outside WinAnsi coverage
        ;
}

export function toPdf(payload: ExportPayload): Buffer {
    const { columns, rows } = tableModel(payload);
    const doc = new jsPDF({ orientation: "landscape", unit: "pt", format: "a4" });
    const pageWidth = doc.internal.pageSize.getWidth();

    const workflowLabel = payload.form.status === "attendance" ? "ATTENDANCE" : payload.form.status === "feedback" ? "FEEDBACK" : "REGISTRATIONS";
    doc.setFont("helvetica", "bold");
    doc.setFontSize(14);
    doc.text(sanitizeForPdf(`${workflowLabel} — ${payload.form.title}`).slice(0, 120), 40, 36);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    doc.setTextColor(90);
    doc.text(
        sanitizeForPdf(
            `${payload.submissions.length} submission${payload.submissions.length === 1 ? "" : "s"} • exported ${formatStamp(new Date().toISOString())} (UTC)` +
            (payload.form.closesAt ? ` • closes ${formatStamp(payload.form.closesAt)} (UTC)` : "")
        ),
        40, 52
    );
    doc.setTextColor(0);

    autoTable(doc, {
        head: [columns.map(c => sanitizeForPdf(c.header))],
        body: rows.map(r => r.map(c => sanitizeForPdf(c))),
        startY: 66,
        margin: { top: 90, left: 40, right: 40, bottom: 46 },
        styles: { fontSize: 8, cellPadding: 4, overflow: "linebreak", valign: "top" },
        headStyles: { fillColor: [30, 64, 175], textColor: 255, fontStyle: "bold" },
        alternateRowStyles: { fillColor: [242, 245, 250] },
        // The table header repeats on every page (autotable default via drawHeader on each page break).
        didDrawPage: () => {
            const page = doc.getCurrentPageInfo().pageNumber;
            if (page > 1) {
                doc.setFont("helvetica", "bold");
                doc.setFontSize(10);
                doc.text(sanitizeForPdf(payload.form.title).slice(0, 100), 40, 34);
                doc.setFont("helvetica", "normal");
                doc.setFontSize(8);
                doc.text(`${page}`, pageWidth - 60, 34);
            }
            doc.setFontSize(8);
            doc.setTextColor(110);
            doc.text(sanitizeForPdf(`Page ${doc.getCurrentPageInfo().pageNumber}`), 40, doc.internal.pageSize.getHeight() - 24);
            doc.setTextColor(0);
        },
    });

    return Buffer.from(doc.output("arraybuffer"));
}

// ── DOCX ────────────────────────────────────────────────────────────────────

export async function toDocx(payload: ExportPayload): Promise<Buffer> {
    const { columns, rows } = tableModel(payload);

    const workflowLabel = payload.form.status === "attendance" ? "Attendance" : payload.form.status === "feedback" ? "Feedback" : "Registrations";
    const headerRow = new TableRow({
        tableHeader: true, // Word repeats this row at the top of every page.
        children: columns.map(c => new TableCell({
            shading: { fill: "1E40AF" },
            margins: { top: 80, bottom: 80, left: 100, right: 100 },
            children: [new Paragraph({ children: [new TextRun({ text: c.header, bold: true, color: "FFFFFF" })] })],
        })),
    });

    const bodyRows = rows.map(r => new TableRow({
        children: r.map(cell => new TableCell({
            margins: { top: 80, bottom: 80, left: 100, right: 100 },
            children: [new Paragraph({
                // Multiline answers keep their line breaks as separate lines.
                children: splitLines(cell).map(line => new TextRun({ text: line, break: 0 })),
            })],
        })),
    }));

    const doc = new Document({
        creator: "ReLU Club admin",
        title: payload.form.title,
        sections: [{
            properties: { page: { size: { orientation: PageOrientation.LANDSCAPE } } },
            children: [
                new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(`${workflowLabel} — ${payload.form.title}`)] }),
                new Paragraph({
                    spacing: { after: 240 },
                    children: [new TextRun({
                        text: `${payload.submissions.length} submission${payload.submissions.length === 1 ? "" : "s"} • exported ${formatStamp(new Date().toISOString())} (UTC)`,
                        color: "666666",
                        size: 18,
                    })],
                }),
                ...(payload.form.description
                    ? [new Paragraph({ children: [new TextRun(payload.form.description)], spacing: { after: 240 } })]
                    : []),
                new Table({
                    width: { size: 100, type: WidthType.PERCENTAGE },
                    rows: [headerRow, ...bodyRows],
                }),
            ],
        }],
    });

    return Packer.toBuffer(doc);
}

function splitLines(s: string): string[] {
    return s.length === 0 ? [""] : s.split(/\r\n|\r|\n/);
}

// ── JSON ────────────────────────────────────────────────────────────────────

export function toJson(payload: ExportPayload): string {
    return JSON.stringify({
        form: payload.form,
        columns: buildExportColumns(payload.form).map(c => c.header),
        exportedAt: new Date().toISOString(),
        submissionCount: payload.submissions.length,
        submissions: payload.submissions.map(s => ({
            id: s.id,
            submittedAt: formatStamp(s.submittedAt) || null,
            userName: s.userName || null,
            userEmail: s.userEmail || null,
            signedIn: Boolean(s.userId),
            answers: s.answers,
        })),
    }, null, 2) + "\n";
}

// ── TXT ─────────────────────────────────────────────────────────────────────

export function toTxt(payload: ExportPayload): string {
    const { columns, rows } = tableModel(payload);
    const width = 78;
    const line = "=".repeat(width);
    const workflowLabel = payload.form.status === "attendance" ? "ATTENDANCE" : payload.form.status === "feedback" ? "FEEDBACK" : "REGISTRATIONS";
    const out: string[] = [];
    out.push(line);
    out.push(`${workflowLabel} — ${payload.form.title}`);
    out.push(`${payload.submissions.length} submission${payload.submissions.length === 1 ? "" : "s"} • exported ${formatStamp(new Date().toISOString())} (UTC)`);
    if (payload.form.description) out.push(`Description: ${payload.form.description}`);
    out.push(line);
    out.push("");

    rows.forEach((r, i) => {
        out.push(`Submission #${i + 1}`);
        out.push("-".repeat(width));
        columns.forEach((c, ci) => {
            const v = (r[ci] ?? "").replace(/\r\n|\r/g, "\n");
            if (!v) return;
            if (v.includes("\n")) {
                out.push(`${c.header}:`);
                v.split("\n").forEach(part => out.push(`    ${part}`));
            } else {
                out.push(`${c.header}: ${v}`);
            }
        });
        out.push("");
    });
    if (payload.submissions.length === 0) out.push("No submissions yet.");
    return out.join("\n") + "\n";
}

// ── HTML ────────────────────────────────────────────────────────────────────

export function toHtml(payload: ExportPayload): string {
    const { columns, rows } = tableModel(payload);
    const esc = escapeHtml;
    const workflowLabel = payload.form.status === "attendance" ? "Attendance" : payload.form.status === "feedback" ? "Feedback" : "Registrations";
    const head = columns.map(c => `<th>${esc(c.header)}</th>`).join("");
    const body = rows.map(r =>
        `<tr>${r.map(cell => {
            const lines = cell.split(/\r\n|\r|\n/);
            return `<td>${lines.map(esc).join("<br/>")}</td>`;
        }).join("")}</tr>`
    ).join("\n");
    const summary = `<p class="meta">${payload.submissions.length} submission${payload.submissions.length === 1 ? "" : "s"} • exported ${esc(formatStamp(new Date().toISOString()))} (UTC)` +
        (payload.form.closesAt ? ` • closes ${esc(formatStamp(payload.form.closesAt))} (UTC)` : "") + "</p>";

    return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>${workflowLabel} — ${esc(payload.form.title)}</title>
<style>
  body { font-family: system-ui, -apple-system, "Segoe UI", sans-serif; margin: 32px; color: #111827; }
  h1 { font-size: 1.5rem; margin-bottom: 4px; }
  .meta { color: #6b7280; font-size: 0.85rem; margin-top: 0; }
  table { border-collapse: collapse; width: 100%; margin-top: 16px; font-size: 0.83rem; }
  th, td { border: 1px solid #d1d5db; padding: 8px 10px; vertical-align: top; text-align: left; }
  th { background: #1e40af; color: #fff; position: sticky; top: 0; }
  tr:nth-child(even) td { background: #f3f6fb; }
  .desc { margin: 8px 0 0; color: #374151; }
</style>
</head>
<body>
<h1>${workflowLabel} — ${esc(payload.form.title)}</h1>
${summary}
${payload.form.description ? `<p class="desc">${esc(payload.form.description)}</p>` : ""}
${payload.submissions.length ? `<table><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>` : "<p>No submissions yet.</p>"}
</body>
</html>`;
}

// ── Router ──────────────────────────────────────────────────────────────────

export async function buildExport(format: ExportFormatId, payload: ExportPayload): Promise<{ body: Buffer; contentType: string; ext: string }> {
    const meta = EXPORT_FORMATS.find(f => f.id === format) ?? EXPORT_FORMATS[0];
    const base = {
        body: Buffer.alloc(0),
        contentType: meta.contentType,
        ext: meta.id === format ? ({ csv: "csv", xlsx: "xlsx", pdf: "pdf", docx: "docx", json: "json", txt: "txt", html: "html" } as Record<ExportFormatId, string>)[format] : "csv",
    };
    switch (format) {
        case "csv": return { ...base, body: Buffer.from(toCsv(payload), "utf8"), ext: "csv" };
        case "xlsx": return { ...base, body: await toXlsx(payload), ext: "xlsx" };
        case "pdf": return { ...base, body: toPdf(payload), ext: "pdf" };
        case "docx": return { ...base, body: await toDocx(payload), ext: "docx" };
        case "json": return { ...base, body: Buffer.from(toJson(payload), "utf8"), ext: "json" };
        case "txt": return { ...base, body: Buffer.from(toTxt(payload), "utf8"), ext: "txt" };
        case "html": return { ...base, body: Buffer.from(toHtml(payload), "utf8"), ext: "html" };
    }
    return base;
}

export function exportFilename(title: string, ext: string): string {
    return `registrations-${slugifyFormTitle(title)}.${ext}`;
}
